            if c < best_cost - 1e-9:
                best, best_cost = new_edges, c
                # alternate with deletion-local-search for synergy
                r = refine(best)
                if tree_cost(r) < best_cost - 1e-9:
                    best, best_cost = r, tree_cost(r)
            else:
                break
        return best

    # Polish the most promising candidates with marginal-cost rerouting.
    candidates.sort(key=tree_cost)
    polished = []
    for c in candidates[:4]:
        p = reroute(c)
        polished.append(p if tree_cost(p) < tree_cost(c) else c)
    candidates = polished + candidates[4:]

    tree_edges = min(candidates, key=tree_cost)

    # --- Emit per-partition paths along the shared tree ---
    tree = h.copy()
    tree.remove_edges_from(
        [e for e in list(tree.edges) if e not in tree_edges])
