def search_algorithm(src, dsts, G, num_partitions):
    """Broadcast src to all dsts via a metric-closure Steiner tree
    (Kou-Markowsky-Berman heuristic).

    1) Compute pairwise shortest paths between all terminals
       (src + dsts) with Dijkstra.
    2) Build the metric closure: a complete undirected graph on the
       terminals whose edge weights are those shortest-path distances.
    3) Take the MST of the closure (nx.minimum_spanning_tree).
    4) Expand each closure edge back to its underlying shortest path;
       the union of those directed edges is a Steiner-tree candidate.
    5) Prune branches ending at non-destination leaves.
    6) Local polish: try removing each tree edge and reconnecting cut
       terminals through the remaining tree; keep strictly cheaper.
    All partitions then route inside the shared tree, so a trunk edge
    is paid once per partition rather than once per destination."""
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = [d for d in dsts if d != src]
    if not terminals:
        return bc_topology

    def edge_cost(s, t):
        return G[s][t].get("cost") or 0

    def tree_cost(edges):
        return sum(edge_cost(s, t) for s, t in edges)

    def prune(edges):
