            if p is not None:
                c = sum(edge_cost(p[k], p[k + 1]) for k in range(len(p) - 1))
                closure.add_edge(nodes[i], nodes[j], weight=c, path=p)

    steiner_edges = set()
    if closure.number_of_edges() >= len(nodes) - 1 and nx.is_connected(closure):
        mst = nx.minimum_spanning_tree(closure, weight="weight")
